Q: How do you guys create DTOs? A: <p>For me I use manual mapping, Why? Because there are some computed properties. If you use automapping you would have to put those properties in the Entities itself, which you can, but there are some special cases automapping fails at..<br />
overall I will provide some examples:</p>
<pre><code>  public static class PlanGroupMapper
  {
      public static readonly Expression&lt;Func&lt;PlanGroupEntity, PlanGroupDto&gt;&gt; FullProjection =
          g =&gt; new PlanGroupDto
          {
              Id = g.Id,
              Title = g.Title,
              Description = g.Description,
              Plans = g.Plans
                  .Select(p =&gt; new PlanDto
                  {
                      Id = p.Id,
                      PlanGroupId = p.PlanGroupId,
                      Price = p.Price,
                      Duration = p.Duration
                  })
                  .ToList()
          };

      public static readonly Expression&lt;Func&lt;PlanGroupEntity, PlanGroupSimplifiedDto&gt;&gt; SimpleProjection =
          g =&gt; new PlanGroupSimplifiedDto
          {
              Id = g.Id,
              Title = g.Title,
              Description = g.Description
          };
  }
</code></pre>
<p>here are the DTOs</p>
<pre><code>  public class PlanGroupSimplifiedDto
  {
      public int Id { get; set; }
      public string Title { get; set; } = string.Empty;
      public string Description { get; set; } = string.Empty;
  }

  public class PlanGroupDto
  {
      public int Id { get; set; }
      public string Title { get; set; } = string.Empty;
      public string Description { get; set; } = string.Empty;

      public ICollection&lt;PlanDto&gt; Plans { get; set; } = new List&lt;PlanDto&gt;();
  }
</code></pre>
<p>and here is how I use the DTOs and mappers</p>
<pre><code>  public interface IPlanGroupService
  {
      Task&lt;ResultViewModel&lt;List&lt;PlanGroupDto&gt;&gt;&gt; GetAllAsync();
      Task&lt;ResultViewModel&lt;PlanGroupDto?&gt;&gt; GetByIdAsync(int id);
  }

  public class PlanGroupService(MediaDbContext db) : IPlanGroupService
  {
      public async Task&lt;ResultViewModel&lt;List&lt;PlanGroupDto&gt;&gt;&gt; GetAllAsync()
      {
          try
          {
              var groups = await db.Groups
                  .AsNoTracking()
                  .Select(PlanGroupMapper.FullProjection)
                  .ToListAsync();

              return new ResultViewModel&lt;List&lt;PlanGroupDto&gt;&gt;(groups);
          }
          catch (Exception ex)
          {
              return new ResultViewModel&lt;List&lt;PlanGroupDto&gt;&gt;(ex.Message, true);
          }
      }

      public async Task&lt;ResultViewModel&lt;PlanGroupDto?&gt;&gt; GetByIdAsync(int id)
      {
          try
          {
              var group = await db.Groups
                  .AsNoTracking()
                  .Where(g =&gt; g.Id == id)
                  .Select(PlanGroupMapper.FullProjection)
                  .FirstOrDefaultAsync();

              if (group == null)
                  return new ResultViewModel&lt;PlanGroupDto?&gt;(&quot;Plan group not found&quot;, true);

              return new ResultViewModel&lt;PlanGroupDto?&gt;(group);
          }
          catch (Exception ex)
          {
              return new ResultViewModel&lt;PlanGroupDto?&gt;(ex.Message, true);
          }
      }
  }
</code></pre>
<p>You can use tdto in the getall so you switch between the two DTOs easily...<br />
as you can see the projection is happening in <code>.select()</code>.</p>

Q: QChart::addAxis() lead to invalid memory address in my code A: <p>The segmentation fault you're experiencing occurs because <strong>the axes don't have a parent when they're added to the chart</strong>. When <code>QChart::addAxis()</code> is called, the chart attempts to take ownership of the axes, but if they were created without a proper parent, this can lead to undefined behavior and memory access violations.</p>
<p>In your original code:</p>
<pre><code>auto* x_axis = new QValueAxis;  // No parent
auto* y_axis = new QValueAxis;  // No parent
</code></pre>
<p>These axes are created without a parent, and when <code>chart-&gt;addAxis()</code> is called, Qt's internal memory management gets confused about ownership, leading to the crash at <code>addSeries()</code>.</p>
<p><strong>Solution</strong></p>
<p><strong>Set the chart as the parent of the axes</strong> before adding them. You have two options:</p>
<h4>Option 1: Set parent in the constructor</h4>
<pre><code>LinearChart::LinearChart(QAbstractAxis* x_axis, QAbstractAxis* y_axis, QWidget* parent)
    : QWidget(parent), x{x_axis}, y{y_axis} {
    // ... create graph and chart ...

    // CRITICAL: Set parent for axes before adding to chart
    x-&gt;setParent(chart);
    y-&gt;setParent(chart);

    // Now it's safe to add axes
    chart-&gt;addAxis(x, Qt::AlignBottom);
    chart-&gt;addAxis(y, Qt::AlignLeft);
    // ...
}
</code></pre>
<h4>Option 2: Create axes with chart as parent</h4>
<pre><code>void setUpChart(QMainWindow* window) {
    auto* chart = new QChart();
    auto* x_axis = new QValueAxis(chart);  // Parent is chart
    auto* y_axis = new QValueAxis(chart);  // Parent is chart

    // ... configure and use axes ...
}
</code></pre>
<h4>Complete Working Code</h4>
<p>Here's your corrected code with the fix applied:</p>
<pre><code>#include &lt;QApplication&gt;
#include &lt;QtCore/QDebug&gt;
#include &lt;QMainWindow&gt;
#include &lt;QWidget&gt;
#include &lt;QtCharts/QValueAxis&gt;
#include &lt;QtCharts/QAbstractAxis&gt;
#include &lt;QtCharts/QLineSeries&gt;
#include &lt;QtCharts/QChart&gt;
#include &lt;QtCharts/QChartView&gt;
#include &lt;QVBoxLayout&gt;

class LinearChart : public QWidget {
public:
    explicit LinearChart(QAbstractAxis* x_axis, QAbstractAxis* y_axis, QWidget* parent = nullptr);
private:
    QAbstractAxis* x;
    QAbstractAxis* y;
    QLineSeries* graph;
    QChart* chart;
    QChartView* view;
};

LinearChart::LinearChart(QAbstractAxis* x_axis, QAbstractAxis* y_axis, QWidget* parent)
    : QWidget(parent), x{x_axis}, y{y_axis} {
    qDebug() &lt;&lt; &quot;Constructor called&quot;;

    // Create graph and chart
    graph = new QLineSeries();
    qDebug() &lt;&lt; &quot;QLineSeries* graph successfully created&quot;;

    chart = new QChart();
    qDebug() &lt;&lt; &quot;QChart* chart successfully created&quot;;

    // CRITICAL FIX: Set parent for axes before adding to chart
    x-&gt;setParent(chart);
    y-&gt;setParent(chart);

    // Add some sample data
    graph-&gt;append(0, 0);
    graph-&gt;append(1, 1);
    graph-&gt;append(2, 4);
    graph-&gt;append(3, 9);
    graph-&gt;append(4, 16);
    graph-&gt;append(5, 25);

    chart-&gt;addSeries(graph);
    qDebug() &lt;&lt; &quot;QLineSeries* graph successfully added to chart&quot;;

    chart-&gt;addAxis(x, Qt::AlignBottom);
    chart-&gt;addAxis(y, Qt::AlignLeft);
    qDebug() &lt;&lt; &quot;QAbstractAxis* axes successfully added to chart&quot;;

    graph-&gt;attachAxis(x);
    graph-&gt;attachAxis(y);
    qDebug() &lt;&lt; &quot;QAbstractAxis* axes successfully attached to graph&quot;;

    // Set chart title
    chart-&gt;setTitle(&quot;Sample Quadratic Graph&quot;);
    chart-&gt;legend()-&gt;hide();

    // Create view
    view = new QChartView(chart, this);
    view-&gt;setRenderHint(QPainter::Antialiasing);

    // Setup layout
    auto *layout = new QVBoxLayout(this);
    layout-&gt;addWidget(view);
    setLayout(layout);
}

void setUpChart(QMainWindow* window) {
    // FIX: Create chart first, then axes with chart as parent
    auto* chart = new QChart();
    auto* x_axis = new QValueAxis(chart);
    auto* y_axis = new QValueAxis(chart);

    // Configure axes
    x_axis-&gt;setTitleText(&quot;X Axis&quot;);
    x_axis-&gt;setRange(0, 6);
    y_axis-&gt;setTitleText(&quot;Y Axis&quot;);
    y_axis-&gt;setRange(0, 30);

    LinearChart* lineplot = new LinearChart(x_axis, y_axis, window);
    lineplot-&gt;setGeometry(QRect(10, 10, 780, 580));
}

int main(int argc, char* argv[]) {
    QApplication app(argc, argv);

    QMainWindow* window = new QMainWindow();
    window-&gt;resize(800, 600);
    window-&gt;setWindowTitle(&quot;Qt Charts Example&quot;);

    setUpChart(window);

    window-&gt;show();
    return app.exec();
}
</code></pre>
